{attribute 'qualified_only'}
TYPE E_PackML_Mode :
(
    ePRODUCTION     := 0,
    eMAINTENANCE    := 1,
    eMANUAL         := 2,
    eIDLE           := 4
) USINT;
END_TYPE

FUNCTION_BLOCK FB_PackML_ModeManager
VAR_INPUT
    xStart          : BOOL;
    xStop           : BOOL;
    xReset          : BOOL;
    xClear          : BOOL;
    xHold           : BOOL;
    xUnhold         : BOOL;
    xSuspend        : BOOL;
    xUnsuspend      : BOOL;
    xAbort          : BOOL;
    xStateComplete  : BOOL;


END_VAR
VAR_OUTPUT
    eState          : E_PackML_State;
    ePrevState      : E_PackML_State;
    xStateChanged   : BOOL;
    xIdle           : BOOL;
    xExecute        : BOOL;
    xStopped        : BOOL;
    xComplete       : BOOL;
    xAborted        : BOOL;
    xHeld           : BOOL;
    xSuspended      : BOOL;
END_VAR
VAR
    xAbortPending   : BOOL;
END_VAR
IMPLEMENTATION ST
IF xAbort THEN
    xAbortPending := TRUE;
END_IF

CASE eState OF

    E_PackML_State.eCLEARING:
        IF xStateComplete THEN
            ePrevState := eState;
            eState := E_PackML_State.eSTOPPED;
            xAbortPending := FALSE;
        END_IF

    E_PackML_State.eSTOPPED:
        IF xReset THEN
            ePrevState := eState;
            eState := E_PackML_State.eRESETTING;
        ELSIF xClear THEN
            ePrevState := eState;
            eState := E_PackML_State.eCLEARING;
        ELSIF xAbortPending THEN
            ePrevState := eState;
            eState := E_PackML_State.eABORTING;
        END_IF

    E_PackML_State.eSTARTING:
        IF xAbortPending THEN
            ePrevState := eState;
            eState := E_PackML_State.eABORTING;
        ELSIF xStateComplete THEN
            ePrevState := eState;
            eState := E_PackML_State.eIDLE;
        END_IF

    E_PackML_State.eEXECUTE:
        IF xAbortPending THEN
            ePrevState := eState;
            eState := E_PackML_State.eABORTING;
        ELSIF xStop THEN
            ePrevState := eState;
            eState := E_PackML_State.eSTOPPING;
        ELSIF xHold THEN
            ePrevState := eState;
            eState := E_PackML_State.eHOLDING;
        ELSIF xSuspend THEN
            ePrevState := eState;
            eState := E_PackML_State.eSUSPENDING;
        ELSIF xStateComplete THEN
            ePrevState := eState;
            eState := E_PackML_State.eCOMPLETING;
        END_IF

    E_PackML_State.eCOMPLETING:
        IF xAbortPending THEN
            ePrevState := eState;
            eState := E_PackML_State.eABORTING;
        ELSIF xStop THEN
            ePrevState := eState;
            eState := E_PackML_State.eSTOPPING;
        ELSIF xStateComplete THEN
            ePrevState := eState;
            eState := E_PackML_State.eCOMPLETE;
        END_IF

    E_PackML_State.eCOMPLETE:
        IF xAbortPending THEN
            ePrevState := eState;
            eState := E_PackML_State.eABORTING;
        ELSIF xStop THEN
            ePrevState := eState;
            eState := E_PackML_State.eSTOPPING;
        ELSIF xReset THEN
            ePrevState := eState;
            eState := E_PackML_State.eRESETTING;
        END_IF

    E_PackML_State.eHOLDING:
        IF xAbortPending THEN
            ePrevState := eState;
            eState := E_PackML_State.eABORTING;
        ELSIF xStop THEN
            ePrevState := eState;
            eState := E_PackML_State.eSTOPPING;
        ELSIF xStateComplete THEN
            ePrevState := eState;
            eState := E_PackML_State.eHELD;
        END_IF

    E_PackML_State.eHELD:
        IF xAbortPending THEN
            ePrevState := eState;
            eState := E_PackML_State.eABORTING;
        ELSIF xStop THEN
            ePrevState := eState;
            eState := E_PackML_State.eSTOPPING;
        ELSIF xUnhold THEN
            ePrevState := eState;
            eState := E_PackML_State.eUNHOLDING;
        END_IF

    E_PackML_State.eUNHOLDING:
        IF xAbortPending THEN
            ePrevState := eState;
            eState := E_PackML_State.eABORTING;
        ELSIF xStop THEN
            ePrevState := eState;
            eState := E_PackML_State.eSTOPPING;
        ELSIF xStateComplete THEN
            ePrevState := eState;
            eState := E_PackML_State.eEXECUTE;
        END_IF

    E_PackML_State.eSUSPENDING:
        IF xAbortPending THEN
            ePrevState := eState;
            eState := E_PackML_State.eABORTING;
        ELSIF xStop THEN
            ePrevState := eState;
            eState := E_PackML_State.eSTOPPING;
        ELSIF xStateComplete THEN
            ePrevState := eState;
            eState := E_PackML_State.eSUSPENDED;
        END_IF

    E_PackML_State.eSUSPENDED:
        IF xAbortPending THEN
            ePrevState := eState;
            eState := E_PackML_State.eABORTING;
        ELSIF xStop THEN
            ePrevState := eState;
            eState := E_PackML_State.eSTOPPING;
        ELSIF xUnsuspend THEN
            ePrevState := eState;
            eState := E_PackML_State.eUNSUSPENDING;
        END_IF

    E_PackML_State.eUNSUSPENDING:
        IF xAbortPending THEN
            ePrevState := eState;
            eState := E_PackML_State.eABORTING;
        ELSIF xStop THEN
            ePrevState := eState;
            eState := E_PackML_State.eSTOPPING;
        ELSIF xStateComplete THEN
            ePrevState := eState;
            eState := E_PackML_State.eEXECUTE;
        END_IF

    E_PackML_State.eSTOPPING:
        IF xAbortPending THEN
            ePrevState := eState;
            eState := E_PackML_State.eABORTING;
        ELSIF xStateComplete THEN
            ePrevState := eState;
            eState := E_PackML_State.eSTOPPED;
        END_IF

    E_PackML_State.eABORTING:
        IF xStateComplete THEN
            ePrevState := eState;
            eState := E_PackML_State.eABORTED;
            xAbortPending := FALSE;
        END_IF

    E_PackML_State.eABORTED:
        IF xStop THEN
            ePrevState := eState;
            eState := E_PackML_State.eSTOPPING;
        ELSIF xClear THEN
            ePrevState := eState;
            eState := E_PackML_State.eCLEARING;
        ELSIF xAbortPending THEN
            xAbortPending := FALSE;
        END_IF

    E_PackML_State.eRESETTING:
        IF xAbortPending THEN
            ePrevState := eState;
            eState := E_PackML_State.eABORTING;
        ELSIF xStateComplete THEN
            ePrevState := eState;
            eState := E_PackML_State.eIDLE;
        END_IF

    E_PackML_State.eIDLE:
        IF xAbortPending THEN
            ePrevState := eState;
            eState := E_PackML_State.eABORTING;
        ELSIF xStop THEN
            ePrevState := eState;
            eState := E_PackML_State.eSTOPPING;
        ELSIF xStart THEN
            ePrevState := eState;
            eState := E_PackML_State.eSTARTING;
        END_IF

END_CASE

IF eState <> ePrevState THEN
    xStateChanged := TRUE;
    ePrevState := eState;
ELSE
    xStateChanged := FALSE;
END_IF

xIdle       := (eState = E_PackML_State.eIDLE);
xExecute    := (eState = E_PackML_State.eEXECUTE);
xStopped    := (eState = E_PackML_State.eSTOPPED);
xComplete   := (eState = E_PackML_State.eCOMPLETE);
xAborted    := (eState = E_PackML_State.eABORTED);
xHeld       := (eState = E_PackML_State.eHELD);
xSuspended  := (eState = E_PackML_State.eSUSPENDED);

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_PackML_Unit
VAR_INPUT
    xEmergencyStop  : BOOL;
    xSafetyOk       : BOOL;
    xPowerOn        : BOOL;
    xRemoteMode                 : BOOL;
    xMachineRunning : BOOL;

END_VAR
VAR_OUTPUT
    eState          : E_PackML_State;
    eMode           : E_PackML_Mode;
    ePrevState      : E_PackML_State;
    xStateChanged   : BOOL;
    xIdle           : BOOL;
    xExecute        : BOOL;
    xStopped        : BOOL;
    xComplete       : BOOL;
    xAborted        : BOOL;
    xHeld           : BOOL;
    xSuspended      : BOOL;
    nStatusWord     : WORD;
    nControlWord    : WORD;
    udiGoodCount    : UDINT;
    udiBadCount     : UDINT;
    udiTotalCount   : UDINT;
END_VAR
VAR
    fbModeManager   : FB_PackML_ModeManager;
    udiGoodCnt      : UDINT;
    udiBadCnt       : UDINT;
    xClearingDone   : BOOL;
    xResettingDone  : BOOL;
    xStartingDone   : BOOL;
    xCompletingDone : BOOL;
    xStoppingDone   : BOOL;
    xAbortingDone   : BOOL;
    xHoldingDone    : BOOL;
    xUnholdingDone  : BOOL;
    xSuspendingDone : BOOL;
    xUnsuspendingDone : BOOL;
    tonClearing     : TON;
    tonResetting    : TON;
    tonStarting     : TON;
    tonCompleting   : TON;
    tonStopping     : TON;
    tonAborting     : TON;
    tonHolding      : TON;
    tonUnholding    : TON;
    tonSuspending   : TON;
    tonUnsuspending : TON;
    tTmpTime        : TIME;
END_VAR
IMPLEMENTATION ST
// ---------------------------------------------------------------------------
// Mode determination
// ---------------------------------------------------------------------------
IF NOT xPowerOn OR NOT xSafetyOk THEN
    eMode := E_PackML_Mode.eIDLE;
ELSIF xEmergencyStop THEN
    eMode := E_PackML_Mode.eIDLE;
ELSIF NOT xRemoteMode THEN
    eMode := E_PackML_Mode.eMANUAL;
ELSE
    eMode := E_PackML_Mode.ePRODUCTION;
END_IF

// ---------------------------------------------------------------------------
// Default timeout for step completion (override per state below)
// ---------------------------------------------------------------------------
tTmpTime := GVL_PackML.UNIT_STATE_TIMEOUT_DEFAULT;

// ---------------------------------------------------------------------------
// State-specific permissives & auto‑complete logic
// ---------------------------------------------------------------------------
CASE fbModeManager.eState OF

    E_PackML_State.eCLEARING:
        tTmpTime := T#5S;
        tonClearing(IN := TRUE, PT := tTmpTime);
        xClearingDone := tonClearing.Q;
        fbModeManager.xStateComplete := xClearingDone;

    E_PackML_State.eSTOPPED:
        tonClearing(IN := FALSE);
        tonResetting(IN := FALSE);
        fbModeManager.xStateComplete := FALSE;

    E_PackML_State.eRESETTING:
        tTmpTime := T#3S;
        tonResetting(IN := TRUE, PT := tTmpTime);
        xResettingDone := tonResetting.Q;
        fbModeManager.xStateComplete := xResettingDone;

    E_PackML_State.eIDLE:
        tonResetting(IN := FALSE);
        tonStarting(IN := FALSE);
        fbModeManager.xStateComplete := FALSE;

    E_PackML_State.eSTARTING:
        tTmpTime := T#3S;
        tonStarting(IN := TRUE, PT := tTmpTime);
        xStartingDone := tonStarting.Q;
        fbModeManager.xStateComplete := xStartingDone;

    E_PackML_State.eEXECUTE:
        tonStarting(IN := FALSE);
        tonCompleting(IN := FALSE);
        tonHolding(IN := FALSE);
        tonSuspending(IN := FALSE);
        fbModeManager.xStateComplete := FALSE;
        IF xMachineRunning THEN
            udiGoodCnt := udiGoodCnt + 1;
        END_IF

    E_PackML_State.eCOMPLETING:
        tTmpTime := T#3S;
        tonCompleting(IN := TRUE, PT := tTmpTime);
        xCompletingDone := tonCompleting.Q;
        fbModeManager.xStateComplete := xCompletingDone;

    E_PackML_State.eCOMPLETE:
        tonCompleting(IN := FALSE);
        fbModeManager.xStateComplete := FALSE;

    E_PackML_State.eHOLDING:
        tTmpTime := T#2S;
        tonHolding(IN := TRUE, PT := tTmpTime);
        xHoldingDone := tonHolding.Q;
        fbModeManager.xStateComplete := xHoldingDone;

    E_PackML_State.eHELD:
        tonHolding(IN := FALSE);
        tonUnholding(IN := FALSE);
        fbModeManager.xStateComplete := FALSE;

    E_PackML_State.eUNHOLDING:
        tTmpTime := T#2S;
        tonUnholding(IN := TRUE, PT := tTmpTime);
        xUnholdingDone := tonUnholding.Q;
        fbModeManager.xStateComplete := xUnholdingDone;

    E_PackML_State.eSUSPENDING:
        tTmpTime := T#2S;
        tonSuspending(IN := TRUE, PT := tTmpTime);
        xSuspendingDone := tonSuspending.Q;
        fbModeManager.xStateComplete := xSuspendingDone;

    E_PackML_State.eSUSPENDED:
        tonSuspending(IN := FALSE);
        tonUnsuspending(IN := FALSE);
        fbModeManager.xStateComplete := FALSE;

    E_PackML_State.eUNSUSPENDING:
        tTmpTime := T#2S;
        tonUnsuspending(IN := TRUE, PT := tTmpTime);
        xUnsuspendingDone := tonUnsuspending.Q;
        fbModeManager.xStateComplete := xUnsuspendingDone;

    E_PackML_State.eSTOPPING:
        tTmpTime := T#3S;
        tonStopping(IN := TRUE, PT := tTmpTime);
        xStoppingDone := tonStopping.Q;
        fbModeManager.xStateComplete := xStoppingDone;

    E_PackML_State.eABORTING:
        tTmpTime := T#2S;
        tonAborting(IN := TRUE, PT := tTmpTime);
        xAbortingDone := tonAborting.Q;
        fbModeManager.xStateComplete := xAbortingDone;

    E_PackML_State.eABORTED:
        tonAborting(IN := FALSE);
        fbModeManager.xStateComplete := FALSE;

END_CASE

// ---------------------------------------------------------------------------
// Call the mode manager
// ---------------------------------------------------------------------------
fbModeManager(
    xStart          := FALSE,
    xStop           := FALSE,
    xReset          := FALSE,
    xClear          := FALSE,
    xHold           := FALSE,
    xUnhold         := FALSE,
    xSuspend        := FALSE,
    xUnsuspend      := FALSE,
    xAbort          := xEmergencyStop OR NOT xSafetyOk,
    xStateComplete  := fbModeManager.xStateComplete
);

// ---------------------------------------------------------------------------
// Mirror outputs
// ---------------------------------------------------------------------------
eState        := fbModeManager.eState;
ePrevState    := fbModeManager.ePrevState;
xStateChanged := fbModeManager.xStateChanged;
xIdle         := fbModeManager.xIdle;
xExecute      := fbModeManager.xExecute;
xStopped      := fbModeManager.xStopped;
xComplete     := fbModeManager.xComplete;
xAborted      := fbModeManager.xAborted;
xHeld         := fbModeManager.xHeld;
xSuspended    := fbModeManager.xSuspended;

// ---------------------------------------------------------------------------
// Product counters
// ---------------------------------------------------------------------------
udiGoodCount  := udiGoodCnt;
udiBadCount   := udiBadCnt;
udiTotalCount := udiGoodCnt + udiBadCnt;

// ---------------------------------------------------------------------------
// OMAC / PackML Status Word (16-bit)
//   Bit 0–4  : State number (0–16)
//   Bit 5    : Suspended
//   Bit 6    : Held
//   Bit 7    : Complete
//   Bit 8    : Stopped
//   Bit 9    : Idle
//   Bit 10   : Execute
//   Bit 11   : Aborted
//   Bit 12   : Resetting
//   Bit 13   : Starting
//   Bit 14   : Alarming (reserved)
//   Bit 15   : Emergency / Fault
// ---------------------------------------------------------------------------
nStatusWord := USINT_TO_WORD(eState);
IF xSuspended  THEN nStatusWord.5  := TRUE; END_IF
IF xHeld       THEN nStatusWord.6  := TRUE; END_IF
IF xComplete   THEN nStatusWord.7  := TRUE; END_IF
IF xStopped    THEN nStatusWord.8  := TRUE; END_IF
IF xIdle       THEN nStatusWord.9  := TRUE; END_IF
IF xExecute    THEN nStatusWord.10 := TRUE; END_IF
IF xAborted    THEN nStatusWord.11 := TRUE; END_IF
IF eState = E_PackML_State.eRESETTING THEN nStatusWord.12 := TRUE; END_IF
IF eState = E_PackML_State.eSTARTING  THEN nStatusWord.13 := TRUE; END_IF
IF xEmergencyStop OR NOT xSafetyOk THEN nStatusWord.15 := TRUE; END_IF

// ---------------------------------------------------------------------------
// OMAC / PackML Control Word (16-bit) — for external HMI/PLC
//   Bit 0  : Start
//   Bit 1  : Stop
//   Bit 2  : Reset
//   Bit 3  : Clear
//   Bit 4  : Hold
//   Bit 5  : Unhold
//   Bit 6  : Suspend
//   Bit 7  : Unsuspend
//   Bit 8  : Abort
//   Bit 9  : Remote / Auto
//   Bit 10 : Reserved
//   Bit 11 : Reserved
//   Bit 12 : Reserved
//   Bit 13 : Reserved
//   Bit 14 : Reserved
//   Bit 15 : Reserved
// ---------------------------------------------------------------------------
nControlWord := 0;
IF xRemoteMode THEN
    nControlWord.9 := TRUE;
END_IF

END_FUNCTION_BLOCK

{attribute 'qualified_only'}
VAR_GLOBAL CONSTANT
    UNIT_STATE_TIMEOUT_DEFAULT : TIME := T#10S;
END_VAR
VAR_GLOBAL
END_VAR

PROGRAM POUexecute
VAR
	iCount:INT;

	t1: TON;
	output: BOOL;
	e1: TIME;
	in1: BOOL;
	a: BOOL;
	b: BOOL;
	c: BOOL;
	out1: BOOL;
	t2: TON;
	out2: INT;
END_VAR
IMPLEMENTATION LD
NETWORK
  EXECUTE
iCount:=icount+1;

  END_EXECUTE ENO EN TRUE;
END_NETWORK
NETWORK
  output := t1 : TON(IN := in1, PT := e1).Q;
END_NETWORK
NETWORK
  split1 := b;
  out1 := (a OR split1) AND c;
  out2 := split1;
END_NETWORK
NETWORK
  output := t2 : TON(IN := , PT := e1).Q;
END_NETWORK

END_PROGRAM

PROGRAM PLC_PRG
VAR
    fbUnit          : FB_PackML_Unit;

    xAtEmergencyStop: BOOL;
    xAtSafetyOk     : BOOL;
    xAtPowerOn      : BOOL;
    xAtRemoteMode   : BOOL;
    xAtMachineRun   : BOOL;

    xHmiStart       : BOOL;
    xHmiStop        : BOOL;
    xHmiReset       : BOOL;
    xHmiClear       : BOOL;
    xHmiHold        : BOOL;
    xHmiUnhold      : BOOL;
    xHmiSuspend     : BOOL;
    xHmiUnsuspend   : BOOL;

    eState          : E_PackML_State;
    eMode           : E_PackML_Mode;
    xIdle           : BOOL;
    xExecute        : BOOL;
    xStopped        : BOOL;
    xComplete       : BOOL;
    xAborted        : BOOL;
    xHeld           : BOOL;
    xSuspended      : BOOL;
    nStatusWord     : WORD;
    nControlWord    : WORD;
    udiGoodCount    : UDINT;
    udiBadCount     : UDINT;
    udiTotalCount   : UDINT;
END_VAR
IMPLEMENTATION ST
// ---------------------------------------------------------------------------
// Drive the PackML unit
// ---------------------------------------------------------------------------
fbUnit(
    xEmergencyStop  := xAtEmergencyStop,
    xSafetyOk       := xAtSafetyOk,
    xPowerOn        := xAtPowerOn,
    xRemoteMode     := xAtRemoteMode,
    xMachineRunning := xAtMachineRun
);

// ---------------------------------------------------------------------------
// Mirror outputs for HMI / SCADA
// ---------------------------------------------------------------------------
eState        := fbUnit.eState;
eMode         := fbUnit.eMode;
xIdle         := fbUnit.xIdle;
xExecute      := fbUnit.xExecute;
xStopped      := fbUnit.xStopped;
xComplete     := fbUnit.xComplete;
xAborted      := fbUnit.xAborted;
xHeld         := fbUnit.xHeld;
xSuspended    := fbUnit.xSuspended;
nStatusWord   := fbUnit.nStatusWord;
nControlWord  := fbUnit.nControlWord;
udiGoodCount  := fbUnit.udiGoodCount;
udiBadCount   := fbUnit.udiBadCount;
udiTotalCount := fbUnit.udiTotalCount;

// ---------------------------------------------------------------------------
// HMI command mapping — feed control word bits to mode manager
//   (to be wired via the control word or direct BOOL I/O)
// ---------------------------------------------------------------------------
// Example: reading HMI buttons
// fbUnit.fbModeManager.xStart     := xHmiStart;
// fbUnit.fbModeManager.xStop      := xHmiStop;
// fbUnit.fbModeManager.xReset     := xHmiReset;
// fbUnit.fbModeManager.xClear     := xHmiClear;
// fbUnit.fbModeManager.xHold      := xHmiHold;
// fbUnit.fbModeManager.xUnhold    := xHmiUnhold;
// fbUnit.fbModeManager.xSuspend   := xHmiSuspend;
// fbUnit.fbModeManager.xUnsuspend := xHmiUnsuspend;

END_PROGRAM

